# compare styles attributes for all cells
diff=[]
for wsname in wbi.sheetnames:
    si=wbi[wsname]; sg=wbg[wsname]
    for r in si.iter_rows():
        for ci in r:
            cg=sg[ci.coordinate]
            # compare style object values relevant: number_format, fill fgColor, font, border, alignment
            attrs=['number_format','fill.patternType','fill.fgColor.rgb','font.name','font.sz','font.bold','border.left.style','alignment.horizontal']
            for a in attrs:
                def get(cell,a):
                    o=cell
                    for p in a.split('.'):
                        o=getattr(o,p)
                    return o
                try:
                    vi=get(ci,a); vg=get(cg,a)
                except Exception as e:
                    continue
                if vi!=vg:
                    diff.append((wsname,ci.coordinate,a,vi,vg))
print('style diffs', len(diff))
for d in diff[:50]: print(d)
